const suit=c=>Math.floor(c/13);
const rank=c=>c%13+2;
const points={10:10,11:11,12:2,13:3,14:4};
function deal(s){
  const deck=Array.from({length:52},(_,i)=>i).filter(c=>rank(c)>=6);
  for(let i=35;i>0;i--){
    s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;
    const j=s.seed%(i+1);
    [deck[i],deck[j]]=[deck[j],deck[i]];
  }
  s.hands=Array.from({length:4},(_,i)=>deck.slice(i*9,i*9+9));
  s.up=deck[35];s.trump=suit(s.up);s.seat=(s.dealer+1)%4;s.trick=[];
}
function legal(s){
  const hand=s.hands[s.seat];
  const follow=s.trick.length?hand.filter(c=>suit(c)===suit(s.trick[0].card)):[];
  return follow.length?follow:hand;
}
const game={
  newMatch(ctx){
    let seed=2166136261;
    for(const p of ctx.players)for(const c of p.id)seed=Math.imul(seed^c.charCodeAt(0),16777619);
    const state={seed:seed>>>0,dealer:3,round:0,scores:[0,0],winners:[]};
    deal(state);
    return {state,turn:[ctx.players[0].id]};
  },
  applyMove(s,id,m,ctx){
    if(!m||Object.keys(m).length!==1||s.winners.length||ctx.players[s.seat].id!==id||!legal(s).includes(m.card))
      throw new InvalidMove("Choose a legal move on your turn.");
    const state={...s,seat:(s.seat+1)%4,scores:[...s.scores],
      hands:s.hands.map((h,i)=>i===s.seat?h.filter(c=>c!==m.card):h),
      trick:[...s.trick,{seat:s.seat,card:m.card}]};
    if(state.trick.length===4){
      const lead=suit(state.trick[0].card);
      const strength=c=>suit(c)===s.trump?50+(rank(c)===11?15:rank(c)):suit(c)===lead?25+rank(c):rank(c);
      state.seat=state.trick.reduce((a,b)=>strength(b.card)>strength(a.card)?b:a).seat;
      state.scores[state.seat%2]+=state.trick.reduce((sum,p)=>sum+(suit(p.card)===s.trump?points[rank(p.card)]??0:0),0);
      state.trick=[];
      if(Math.max(...state.scores)>=41){
        state.winners=ctx.players.flatMap((_,i)=>state.scores[i%2]>=41?[i]:[]);
        const humans=ctx.players.filter(p=>p.kind==="human"&&p.active!==false);
        const winners=humans.filter(p=>state.winners.includes(ctx.players.indexOf(p)));
        const paid=winners.length?winners:humans;
        return {state,turn:null,payouts:Object.fromEntries(paid.map((p,i)=>[p.id,
          Math.floor(ctx.pot/paid.length)+Number(i<ctx.pot%paid.length)]))};
      }
      if(state.hands.every(h=>!h.length)){
        state.round++;
        state.dealer=(state.dealer+1)%4;
        deal(state);
      }
    }
    return {state,turn:[ctx.players[state.seat].id]};
  },
  viewFor(s,id,ctx){
    const {hands,seed,...visible}=s;
    const i=ctx.players.findIndex(p=>p.id===id);
    return {...visible,hand:hands[i]??[],legal:i===s.seat?legal(s):[]};
  },
  computerMove(s){
    const strength=c=>suit(c)===s.trump?50+(rank(c)===11?15:rank(c)):rank(c);
    return {card:[...legal(s)].sort((a,b)=>strength(b)-strength(a))[0]};
  },
  randomMove(s,id,ctx){
    const options=legal(s);
    return {card:options[Math.floor(ctx.random()*options.length)]};
  }
};

